<?php
declare(strict_types=1); require __DIR__.'/app/bootstrap.php'; if(current_user())redirect('dashboard'); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$ip=substr($_SERVER['REMOTE_ADDR']??'unknown',0,45);$attempts=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE email=? AND ip_address=? AND attempted_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$attempts->execute([$email,$ip]);if((int)$attempts->fetchColumn()>=5){$error='Too many sign-in attempts. Try again in 15 minutes.';}else{$stmt=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$stmt->execute([$email]);$record=$stmt->fetch();if(!$record||!$record['is_active']||!password_verify($_POST['password']??'',$record['password_hash'])){db()->prepare('INSERT INTO login_attempts(email,ip_address) VALUES(?,?)')->execute([$email,$ip]);$error='Email or password is incorrect.';}else{db()->prepare('DELETE FROM login_attempts WHERE email=? AND ip_address=?')->execute([$email,$ip]);session_regenerate_id(true);$_SESSION['user_id']=$record['id'];redirect('dashboard');}}}
$pageTitle='Sign in';require __DIR__.'/includes/auth-header.php';?>
<section class="auth-card compact"><p class="kicker">WELCOME BACK</p><h1>Sign in to Nonagon.</h1><p>Continue to your company workspace.</p><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><form method="post" class="stack"><?=csrf_field()?><label>Email address<input type="email" name="email" autocomplete="email" required autofocus></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button class="primary" type="submit">Sign in <span>→</span></button></form><p class="alternate">New to Nonagon? <a href="register">Create an account</a></p></section>
<?php require __DIR__.'/includes/auth-footer.php';?>
